          "title": "تعريف async function",
          "englishTitle": "تعريف async function",
          "definition": "يُقصد بـ (تعريف async function) أحد المفاهيم المحورية في مسار Async وAwait ضمن بيئة Node.js؛ حيث يوفر للمهندس الأدوات المعمارية والبرمجية لمعالجة تدفقات البيانات وتقديم أداء عالي الاستقرار في بيئات الإنتاج الحية.",
          "analogy": "تشبه وعود Promises طلب شراء سلعة من متجر إلكتروني؛ تستلم فوراً وصل الشراء (Promise) الذي يتحول لاحقاً إما إلى سلعة مستلمة (Resolved) أو اعتذار عن نفاد الكمية (Rejected).",
          "why": "تبرز أهمية (تعريف async function) في حل مشكلات الاختناق البرمجي، ضمان استقرار الخدمات الخلفية عند تزايد أحمال المستخدمين، وفصل المسؤوليات لتحقيق كود نظيف وسهل الصيانة والاختبار.",
